// About: the transparency report (calm about). What the framework does that you did not
// write: the request pipeline in order, headers, stored data and its lifetime, logging,
// the hosts the code can reach, and every file the CLI writes. Generated by calm/about.js
// from the running app and the code on disk.

import { h, mount, api, bar, fileLink, loading, errorBox, empty } from '../lib.js';
import { store } from '../store.js';

export default {
  id: 'about',
  label: 'About',
  mount: mountAbout,
};

const ttlText = (ttl) => (!ttl ? 'kept until deleted' : ttl.seconds === 0 ? `deleted at ${ttl.field}` : `deleted ${duration(ttl.seconds)} after ${ttl.field}`);
const duration = (s) => (s % 86_400 === 0 ? `${s / 86_400} days` : s % 3600 === 0 ? `${s / 3600} hours` : s % 60 === 0 ? `${s / 60} minutes` : `${s} s`);

function card(title, ...kids) {
  return h('section', { class: 'ab-card' }, h('h2', { class: 'ab-title' }, title), kids);
}

function mountAbout(root) {
  const body = h('div', { class: 'scroll ab' }, loading('Reading the framework'));
  mount(root, h('div', { class: 'panel' }, bar('About', h('span', { class: 'bar-meta' }, 'What the framework does that you did not write')), body));
  const appRoot = store.overview?.app?.root ?? null;
  const link = (file) => (file ? fileLink(appRoot, file) : null);

  api('/about')
    .then((a) => {
      const f = a.framework;
      const o = a.outbound;
      mount(
        body,
        h('div', { class: 'ab-head' }, h('p', null, `calmapi ${f.calmapi ?? '?'} · node ${f.node} · express ${f.express ?? '?'} · mongoose ${f.mongoose ?? '?'} · ${f.mode}`), h('p', { class: 'muted' }, 'Generated from your calm/ and app/ code, so it cannot drift from it. The same report: npx calm about, or calm_about for agents.')),
        card(
          'Request pipeline, in the order it runs',
          h('ol', { class: 'ab-pipe' }, a.pipeline.map((p) => h('li', null, h('span', { class: 'mono ab-name' }, p.name), h('span', { class: 'ab-purpose' }, p.purpose, p.when ? h('span', { class: 'muted' }, ` (${p.when})`) : null), p.from !== 'calm' ? h('span', { class: 'muted' }, p.from) : null, link(p.file)))),
        ),
        card(
          'Headers',
          h('table', { class: 'ab-table' }, h('tbody', null, [...a.headers.always, ...a.headers.rateLimit].map((x) => h('tr', null, h('td', { class: 'mono' }, x.name), h('td', { class: 'mono muted' }, x.value), h('td', { class: 'muted' }, x.when ?? ''))))),
          h('p', { class: 'muted' }, `Removed: ${a.headers.removed.join(', ')}. CORS origins: ${typeof a.headers.cors.origins === 'string' ? a.headers.cors.origins : a.headers.cors.origins.join(', ') || 'none'}.`),
        ),
        card(
          'Stored data',
          h('table', { class: 'ab-table' }, h('tbody', null, a.stored.collections.map((x) => h('tr', null, h('td', { class: 'mono' }, x.collection), h('td', { class: 'muted' }, x.owner), h('td', null, ttlText(x.ttl)), h('td', null, x.encryptedFields.length ? `encrypted: ${x.encryptedFields.join(', ')}` : ''), h('td', { class: 'muted' }, x.note ?? ''))))),
          a.stored.memory.map((m) => h('p', null, h('b', null, m.name), `: ${m.what} `, h('span', { class: 'muted' }, `(${m.where}; ${m.retention})`))),
        ),
        card('Logging', h('p', null, `Level ${a.logging.level}, ${a.logging.format}. Access log: ${a.logging.accessLog.fields.join(', ')}, e.g. `, h('code', null, a.logging.accessLog.example)), h('p', null, `${a.logging.never}.`), h('p', { class: 'muted' }, `Devtools: ${a.logging.devtools.records}. Redacts ${a.logging.devtools.redacts}. ${a.logging.devtools.where}.`)),
        card(
          'Hosts the code can reach',
          h('p', { class: ['ab-promise', o.promise.ok ? 'ok' : 'bad'] }, o.promise.ok ? '✔ ' : '✖ ', o.promise.text, h('span', { class: 'muted' }, ` (${o.promise.detail})`)),
          o.hosts.length ? h('table', { class: 'ab-table' }, h('tbody', null, o.hosts.map((x) => h('tr', null, h('td', { class: 'mono' }, x.host), h('td', null, x.files.map((file) => link(file))))))) : empty('No host names in app/ or calm/.'),
          o.dynamic.map((d) => h('p', { class: 'muted' }, link(d.file), ` ${d.note}`)),
        ),
        card('Files the CLI writes', h('table', { class: 'ab-table' }, h('tbody', null, a.files.map((x) => h('tr', null, h('td', { class: 'mono' }, x.path), h('td', null, h('b', null, x.by), h('div', { class: 'muted' }, x.when))))))),
        a.blocks.length ? card('Blocks', h('table', { class: 'ab-table' }, h('tbody', null, a.blocks.map((b) => h('tr', null, h('td', { class: 'mono' }, b.name), h('td', null, link(b.file)), h('td', { class: 'muted' }, b.env.join(', ')), h('td', { class: 'muted' }, b.models.join(', '))))))) : null,
      );
    })
    .catch((err) => mount(body, errorBox(err)));
}
